{"original_documents": [{"name": "api_worker.json", "sha256": "478c4a1da62bd9facaa847212d0e585c79f2cb36df101643e8d9640a851c7cf0", "saved_as": "input_01.txt", "text": "{
  "classification": "OPERATOR_RELEASED_LAB_ONLY",
  "requirements": [],
  "context_documents": [
    {
      "id": "SYSTEM_DESIGN",
      "title": "合成システム設計資料：api_worker",
      "content": {
        "system": {
          "purpose": "画像を受け付け、非同期で変換して処理結果を照会する",
          "current": {
            "api": {
              "id": "upload_api",
              "hosting": "Kubernetes Deployment",
              "runtime": "Python 3.11 / Linux OCI container",
              "interface": {
                "protocol": "HTTPS",
                "exposure": "public"
              },
              "reads_aws_apis": [
                "DynamoDB GetItem"
              ],
              "writes_aws_apis": [
                "S3 PutObject",
                "SQS SendMessage"
              ],
              "readiness": {
                "path": "/ready",
                "protocol": "HTTP"
              },
              "replicas_observed": 1,
              "pvc_references_observed": false
            },
            "worker": {
              "id": "image_worker",
              "hosting": "Kubernetes Deployment",
              "runtime": "Python 3.11 / Linux OCI container",
              "interface": "no inbound HTTP",
              "reads_aws_apis": [
                "SQS ReceiveMessage",
                "S3 GetObject"
              ],
              "writes_aws_apis": [
                "DynamoDB PutItem"
              ],
              "processing_duration": "not measured"
            },
            "data": {
              "uploads": "existing Amazon S3 bucket",
              "queue": "existing Amazon SQS queue",
              "status": "existing Amazon DynamoDB table",
              "durability": "upload objects and processing status must be retained"
            },
            "relations": [
              {
                "from": "upload_api",
                "to": "existing Amazon S3 bucket",
                "purpose": "store uploaded image"
              },
              {
                "from": "upload_api",
                "to": "existing Amazon SQS queue",
                "purpose": "enqueue conversion job"
              },
              {
                "from": "existing Amazon SQS queue",
                "to": "image_worker",
                "purpose": "consume conversion job"
              },
              {
                "from": "image_worker",
                "to": "existing Amazon DynamoDB table",
                "purpose": "record processing result"
              },
              {
                "from": "upload_api",
                "to": "existing Amazon DynamoDB table",
                "purpose": "query processing result"
              }
            ]
          },
          "constraints": [
            "コンテナの再配置と認証方式の変更は承認済み。アプリの外部API互換性と処理結果を維持する。",
            "S3・SQS・DynamoDBの既存データと接続先を引き継ぐ。データ消去や新規サービスへの置換は未承認。",
            "APIの外部公開は必要。ワーカーの受信用HTTP公開は不要。AWS接続先以外への外向き通信は未承認。",
            "必要な処理件数、レプリカ数、タイムアウト、可用性目標は未測定。観測値を目標値にはしない。",
            "移行時の未処理メッセージ、処理の重複、元データとの照合、切戻し時の配送を確認する。"
          ]
        }
      },
      "source_reference": "SYNTHETIC_EVALUATION_NOT_REAL_CUSTOMER_OR_DISCOVERY"
    }
  ]
}"}], "technical_reference_documents": [{"name": "sources.json", "sha256": "b0de039de12ab19f533f59acf9511a9c41bc3c59f6fbc52166dc4587c47a7320", "saved_as": "source_01.txt", "text": "{
  "kind": "AUTHOR_RESEARCH_NOTES_NOT_VERBATIM_SOURCE",
  "checked_date_jst": "2026-11-18",
  "scope": "Official pages consulted for the independent design demonstration. These notes are not raw quotes, complete documentation, or proof that a proposed deployment meets every requirement.",
  "sources": [
    {
      "label": "S1",
      "title": "Amazon EBS volumes",
      "url": "https://docs.aws.amazon.com/ebs/latest/userguide/ebs-volumes.html",
      "note": "EBS is persistent block storage attached to EC2. A filesystem on EBS supports ordinary file I/O. Volume and instance placement, lifecycle settings and backups need separate design. Storage persistence does not prove application transaction durability."
    },
    {
      "label": "S2",
      "title": "Cutover stage — AWS Prescriptive Guidance",
      "url": "https://docs.aws.amazon.com/prescriptive-guidance/latest/best-practices-migration-cutover/cutover-stage.html",
      "note": "Cutover coordinates ingestion, final data synchronization, routing and testing. Rollback after new writes must account for changed data rather than simply reverting traffic. Select the mechanism from actual application and data behavior, and rehearse it."
    },
    {
      "label": "S3",
      "title": "Amazon ECS task IAM role",
      "url": "https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task-iam-roles.html",
      "note": "The task role supplies application-container AWS permissions. It is distinct from credentials for the ECS/Fargate agent. EC2 instance profiles are not available to containers on Fargate as an application credential mechanism. Match each permission to the actual task caller and resource."
    },
    {
      "label": "S4",
      "title": "Amazon ECS task execution IAM role",
      "url": "https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task_execution_IAM_role.html",
      "note": "The execution role is for platform operations, including applicable private ECR image pulls and awslogs delivery. Its credentials are not directly available as application-container credentials. Secret injection and other selected features can require additional platform permissions."
    },
    {
      "label": "S5",
      "title": "Health checks for Application Load Balancer target groups",
      "url": "https://docs.aws.amazon.com/elasticloadbalancing/latest/application/target-group-health-checks.html",
      "note": "Target checks use selected HTTP/HTTPS protocol, target port, path and success criteria. An existing readiness path can be considered if the target exposes compatible behavior. External client HTTPS and internal HTTP health checks are different interfaces. Target capacity/observed counts do not specify health-check timing."
    },
    {
      "label": "S6",
      "title": "Amazon ECR interface VPC endpoints",
      "url": "https://docs.aws.amazon.com/AmazonECR/latest/userguide/vpc-endpoints.html",
      "note": "Private ECR access requires the appropriate API/DKR endpoints and S3 layer-download path for the selected runtime/platform. Check DNS, security groups and policies. Some first pull-through cache fetches need external connectivity; do not assume that every registry path works in an isolated network."
    },
    {
      "label": "S7",
      "title": "Amazon SQS at-least-once delivery",
      "url": "https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/standard-queues-at-least-once-delivery.html",
      "note": "Standard-queue duplicate delivery is possible. Receiving a message is not evidence of exactly-once application processing. Identify actual idempotency, acknowledgement and completion behavior before claiming safe concurrent consumers or rollback. Queue type must be checked."
    },
    {
      "label": "S8",
      "title": "Amazon SQS visibility timeout",
      "url": "https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-visibility-timeout.html",
      "note": "Received messages are hidden temporarily, not removed merely by ReceiveMessage. Completion needs deletion, possibly through SDK behavior. Visibility expiry can expose work again. Set or extend visibility from actual processing needs, not replica counts."
    },
    {
      "label": "S9",
      "title": "Native PostgreSQL client applications — AWS Prescriptive Guidance",
      "url": "https://docs.aws.amazon.com/prescriptive-guidance/latest/migration-databases-postgresql-ec2/native-postgre-sql-client-applications.html",
      "note": "Native dump/restore is an offline PostgreSQL migration option. Assess version compatibility, global objects, size, transfer/storage needs and downtime. This is a possible later database move, not evidence that an application-only move requires replacing its existing database."
    },
    {
      "label": "S10",
      "title": "Deploy private clusters with limited internet access — Amazon EKS",
      "url": "https://docs.aws.amazon.com/eks/latest/userguide/private-clusters.html",
      "note": "Without outbound internet, plan private cluster endpoint access, image distribution and node/Pod service dependencies. Required service endpoints vary with selected features and identity mechanisms. Choosing EKS alone does not satisfy an isolated-environment requirement."
    },
    {
      "label": "S11",
      "title": "Gateway endpoints — Amazon VPC",
      "url": "https://docs.aws.amazon.com/vpc/latest/privatelink/gateway-endpoints.html",
      "note": "S3 and DynamoDB support gateway endpoint connectivity without NAT or internet gateway for the VPC. Gateway endpoints are different from PrivateLink interface endpoints. Check service region, route-table associations, resource and endpoint policies."
    },
    {
      "label": "S12",
      "title": "Internetwork traffic privacy in Amazon SQS",
      "url": "https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-internetwork-traffic-privacy.html",
      "note": "SQS interface endpoints provide private HTTPS API connectivity. Confirm private DNS/endpoint form and endpoint policy. SQS data delivered to a consumer does not mean SQS initiates an inbound connection to that application's HTTP server."
    },
    {
      "label": "S13",
      "title": "Application Load Balancers",
      "url": "https://docs.aws.amazon.com/elasticloadbalancing/latest/application/application-load-balancers.html",
      "note": "An ALB has selected subnets, listeners, target groups and security groups. For a conventional regional ALB, account for Availability Zone placement requirements. A load balancer does not itself make a single backend application highly available."
    },
    {
      "label": "S14",
      "title": "Assess — AWS Well-Architected Migration Lens",
      "url": "https://docs.aws.amazon.com/wellarchitected/latest/migration-lens/assess-rel.html",
      "note": "Establish application service/recovery goals, validate runbooks and rehearse the migration window. Plan for failure and for data recovery when reverting. These are design/review criteria, not a service-mapping recipe or proof of approval."
    },
    {
      "label": "S15",
      "title": "Ollama API chat",
      "url": "https://docs.ollama.com/api/chat",
      "note": "The prototype uses POST /api/chat with messages, model, stream=false, think and generation options. Thinking support depends on model/server. Record done reason and prompt/evaluation statistics; a normal stop is not a semantic-quality decision."
    }
  ]
}
"}]}
